package config

import (
	"encoding/json"
	"os"
)

type Values struct {
	Region string `json:"region"`
}

type LookupEnv func(string) (string, bool)

func Load(path string, lookup LookupEnv) (Values, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return Values{}, err
	}
	var values Values
	if err := json.Unmarshal(data, &values); err != nil {
		return Values{}, err
	}
	if region, _ := lookup("APP_REGION"); region != "" {
		values.Region = region
	}
	return values, nil
}
package config

import (
	"os"
	"path/filepath"
	"testing"
)

func TestEnvironmentPrecedence(t *testing.T) {
	dir := t.TempDir()
	path := filepath.Join(dir, "config.json")
	if err := os.WriteFile(path, []byte(`{"region":"ap-northeast-1"}`), 0o644); err != nil {
		t.Fatal(err)
	}
	lookup := func(string) (string, bool) { return "eu-west-1", true }
	values, err := Load(path, lookup)
	if err != nil {
		t.Fatal(err)
	}
	if values.Region != "eu-west-1" {
		t.Fatalf("region=%q", values.Region)
	}
}
package config

import "os"

// LegacyRegion is retained for an old integration and is not used by envmerge.
func LegacyRegion(fileValue string) string {
	if value := os.Getenv("APP_REGION"); value != "" {
		return value
	}
	return fileValue
}
package main

import (
	"fmt"
	"os"

	"example.com/envmerge/internal/config"
)

func main() {
	loaded, err := config.Load("config.json", os.LookupEnv)
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	fmt.Println(loaded.Region)
}

